 private AppRegressionTest base;private MainActivity a;private VehicleCoordinator model;
 @Before public void start()throws Exception{base=new AppRegressionTest();base.start();Field f=AppRegressionTest.class.getDeclaredField("activity");f.setAccessible(true);a=(MainActivity)f.get(base);model=VehicleCoordinator.get(a);set(model,"signedIn",true);model.selected=new io.github.polestarcn.companion.api.ChinaPolestarApi.VehicleInfo();model.selected.vin="V086-FIXTURE";model.snapshot=sample("已上锁");AppPreferences.set(a,"language","zh");}
 @After public void stop(){AlertDialog dialog=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();if(dialog!=null)dialog.dismiss();base.stop();}
 private void set(Object o,String name,Object value)throws Exception{Field f=o.getClass().getDeclaredField(name);f.setAccessible(true);f.set(o,value);}
 private void invoke(String name)throws Exception{Method m=MainActivity.class.getDeclaredMethod(name);m.setAccessible(true);m.invoke(a);}
 private VehicleSnapshot sample(String lock){long now=System.currentTimeMillis();return new VehicleSnapshot("Polestar 2","masked",63,230,65845,"充电中","全部关闭","全部关闭","已关闭",lock,now,"LIVE",false,"开启","关闭").withHealth(new VehicleHealthSnapshot(1,1,1,now,1,1,1,-1,1,931,75,14959)).withEnvironment(new EnvironmentSnapshot("开启","关闭",33.0,22.0,3.0,4,15,0,now,now)).withCharging(new ChargingSnapshot(1,2,4,80,6000.0,25.0));}
 private View root(){return a.getWindow().getDecorView();}
 private View tag(String key){View v=root().findViewWithTag(key);assertNotNull(key,v);return v;}
 private View render(int width,int height,float font)throws Exception{Configuration c=new Configuration(a.getResources().getConfiguration());c.screenWidthDp=width;c.screenHeightDp=height;c.fontScale=font;android.util.DisplayMetrics d=a.getResources().getDisplayMetrics();d.scaledDensity=d.density*font;a.getResources().updateConfiguration(c,d);invoke("render");View v=root();v.measure(View.MeasureSpec.makeMeasureSpec(width,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(height,View.MeasureSpec.EXACTLY));v.layout(0,0,width,height);return v;}
 private void fits(View v){if(v.getVisibility()!=View.VISIBLE)return;if(v instanceof TextView){TextView t=(TextView)v;if(!(t instanceof VehicleConditionButton)&&t.length()>0&&t.getLayout()!=null)assertTrue("tag="+t.getTag()+" text="+t.getText()+" layout="+t.getLayout().getHeight()+" actual="+t.getHeight(),t.getLayout().getHeight()<=t.getHeight()-t.getCompoundPaddingTop()-t.getCompoundPaddingBottom());}if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++)fits(((ViewGroup)v).getChildAt(i));}
 @Test public void conditionModesRemainClickableAcrossSkinsAndBothLanguages()throws Exception{for(String skin:UiSkin.CHOICES)for(String lang:new String[]{"zh","en"})for(String mode:new String[]{"bar","percent","text"}){UiSkin.set(a,skin);AppPreferences.set(a,"language",lang);AppPreferences.set(a,"condition_display",mode);render(360,780,1);VehicleConditionButton b=(VehicleConditionButton)tag("exterior_button");assertTrue(b.isEnabled());assertEquals(!mode.equals("text"),b.getContentDescription().toString().contains("21%"));assertEquals(b.getHeight(),tag("camp_button").getHeight());b.performClick();android.app.AlertDialog popup=org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog();assertNotNull(popup.findViewById(android.R.id.content).findViewWithTag("car_condition_popup"));popup.dismiss();}}
 @Test public void largerFontAndIndependentWeightsFitAllSkins()throws Exception{AppPreferences.set(a,"ui_data_bold","on");AppPreferences.set(a,"ui_button_bold","on");AppPreferences.set(a,"feedback_bold","on");AppPreferences.set(a,"feedback_sp","14");for(String skin:UiSkin.CHOICES)for(String lang:new String[]{"zh","en"})for(int[] size:new int[][]{{320,568},{360,780},{640,320}}){UiSkin.set(a,skin);AppPreferences.set(a,"language",lang);View v=render(size[0],size[1],1.3f);try{fits(v);}catch(AssertionError e){throw new AssertionError(skin+" "+lang+" "+Arrays.toString(size),e);}}}
 @Test public void parkingCaptionUsesFlexibleWidthInEverySkin()throws Exception{for(String skin:UiSkin.CHOICES){UiSkin.set(a,skin);render(360,780,1);assertTrue(skin,tag("parking_caption").getWidth()>100);assertEquals(1,((TextView)tag("parking_caption")).getMaxLines());}}
 @Test public void climateDefaultsRetainTargetRunningAndTimeWithoutCabin(){String text=ButtonFeedback.value(a,"climate",model.snapshot,"运行中");assertTrue(text.contains("22°"));assertTrue(text.contains("运行中"));assertTrue(text.contains("15"));assertFalse(text.contains("33.0"));AppPreferences.set(a,"feedback_climate","temperature");assertTrue(ButtonFeedback.value(a,"climate",model.snapshot,"").contains("33.0"));AppPreferences.set(a,"feedback_climate","hidden");assertEquals("",ButtonFeedback.value(a,"climate",model.snapshot,""));}
 @Test public void tripTimesUseSameHmUnitsAndNoEstimatePrefix(){for(boolean english:new boolean[]{false,true}){assertEquals("1h 15m",MileageSnapshot.durationText(75.0,english));assertEquals("5m",MileageSnapshot.durationText(5.0,english));assertEquals("--",MileageSnapshot.durationText(null,english));assertFalse(DisplayMetric.TA_DURATION.shortLabel(english).contains("~"));}}
 @Test public void healthMetricsUseActualStatesAndKeepUnknownAsMissing(){assertEquals("正常",DisplayMetric.BATTERY_12V.value(a,model.snapshot,true,false));assertEquals("Normal",DisplayMetric.BRAKE_FLUID.value(a,model.snapshot,true,true));assertEquals("--",DisplayMetric.OIL_STATUS.value(a,model.snapshot,true,true));assertEquals(model.snapshot.health.reportedAt,DisplayMetric.COOLANT.reportedAt(model.snapshot));}
 @Test public void draggableOrderAndAccessibleArrowsPersistAcrossDashboardLayouts()throws Exception{MetricOrderView order=new MetricOrderView(a,Arrays.asList(DisplayMetric.TM_DISTANCE,DisplayMetric.BATTERY_12V,DisplayMetric.BRAKE_FLUID));order.findViewWithTag("down_tm_distance").performClick();assertEquals(DisplayMetric.BATTERY_12V,order.values().get(0));order.move(2,0);assertEquals(DisplayMetric.BRAKE_FLUID,order.values().get(0));MetricSelection.save(a,"home_metrics",order.values());for(String skin:UiSkin.CHOICES){UiSkin.set(a,skin);render(360,780,1);assertNotNull(root().findViewWithTag("home_value_brake_fluid"));}assertEquals(order.values(),MetricSelection.read(a,"home_metrics",""));}
 @Test public void mergedVoLikeSupportsButtonAndRightSwipe()throws Exception{assertEquals(6,UiSkin.pickerChoices().length);UiSkin.set(a,UiSkin.SIMPLE);render(360,780,1);assertNull(root().findViewWithTag("volike_detail_rail"));tag("volike_detail_toggle").performClick();render(360,780,1);assertNotNull(tag("volike_detail_rail"));HorizontalSwipeRefreshLayout refresh=(HorizontalSwipeRefreshLayout)tag("control_pull_refresh");long t=SystemClock.uptimeMillis();refresh.dispatchTouchEvent(MotionEvent.obtain(t,t,MotionEvent.ACTION_DOWN,10,100,0));refresh.dispatchTouchEvent(MotionEvent.obtain(t,t+200,MotionEvent.ACTION_UP,150,105,0));assertFalse(UiSkin.detailedView(a));}
 private View widget(String style,WidgetRenderer.Size size,int w,int h,VehicleSnapshot vehicle){AppPreferences.set(a,"widget_design",style);View v=WidgetRenderer.createViews(a,86,size,w,h,null,vehicle).apply(a,new FrameLayout(a));v.measure(View.MeasureSpec.makeMeasureSpec(w,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(h,View.MeasureSpec.EXACTLY));v.layout(0,0,w,h);return v;}
 @Test public void widgetLockGlyphFollowsReportedStateInEveryStyleAndSize(){for(String style:new String[]{VoLikeWidgetRenderer.CLASSIC,VoLikeWidgetRenderer.SIMPLE,VoLikeWidgetRenderer.DETAILED,VoLikeWidgetRenderer.POLESTAR,VoLikeWidgetRenderer.PSEU})for(WidgetRenderer.Size size:WidgetRenderer.Size.values()){WidgetButtons.save(a,size,Arrays.asList("lock","climate"));for(String lock:new String[]{"已上锁","未锁"}){View v=widget(style,size,380,170,sample(lock));ImageView icon=v.findViewById(R.id.widget_lock_icon);assertEquals(lock.equals("未锁")?R.drawable.ic_unlock:R.drawable.ic_lock,Shadows.shadowOf(icon.getDrawable()).getCreatedFromResId());}}}
 @Test public void fiveByOneOffersFiveSelectableControlsAndAdaptsWhenResized(){WidgetButtons.save(a,WidgetRenderer.Size.EXTRA_WIDE,Arrays.asList("lock","climate","air","trunk","windows"));for(String style:new String[]{VoLikeWidgetRenderer.CLASSIC,VoLikeWidgetRenderer.SIMPLE,VoLikeWidgetRenderer.DETAILED,VoLikeWidgetRenderer.POLESTAR,VoLikeWidgetRenderer.PSEU}){View v=widget(style,WidgetRenderer.Size.EXTRA_WIDE,380,70,model.snapshot);fits(v);ViewGroup actions=v.findViewById(R.id.widget_action_row);int visible=0;for(int i=0;i<actions.getChildCount();i++)if(actions.getChildAt(i).getVisibility()==View.VISIBLE){visible++;assertTrue(actions.getChildAt(i).getWidth()>=48);}assertEquals(5,visible);v=widget(style,WidgetRenderer.Size.EXTRA_WIDE,269,51,model.snapshot);fits(v);assertEquals(View.GONE,v.findViewById(R.id.widget_action_extra4).getVisibility());}}
 @Test public void backgroundPolicyCanDisableBothAndUsesFastestSharedSource(){assertEquals(30,RefreshPolicy.background(a,true,true));AppPreferences.set(a,"app_background_minutes","60");AppPreferences.set(a,"widget_refresh_minutes","15");assertEquals(15,RefreshPolicy.background(a,true,true));assertEquals(60,RefreshPolicy.background(a,true,false));AppPreferences.set(a,"widget_refresh_minutes","0");AppPreferences.set(a,"app_background_minutes","0");assertEquals(0,RefreshPolicy.background(a,true,true));AppPreferences.set(a,"foreground_refresh_minutes","-5");assertEquals(5,RefreshPolicy.foreground(a));}
 @Test public void foregroundAndVehicleMapSettingsAreIndependent(){AppPreferences.set(a,"map_refresh_minutes","60");AppPreferences.set(a,"map_phone_location","off");assertEquals(60,RefreshPolicy.map(a));assertFalse(MapLocationPermission.enabled(a));AppPreferences.set(a,"foreground_refresh_minutes","1");assertEquals(1,RefreshPolicy.foreground(a));assertEquals(60,RefreshPolicy.map(a));}
 @Test public void phoneLocationHasNoGeolocationGrantUntilExplicitSecondaryPreviewRequest(){Shadows.shadowOf(a.getApplication()).grantPermissions(android.Manifest.permission.ACCESS_COARSE_LOCATION);AppPreferences.set(a,"map_phone_location","on");AppPreferences.set(a,"phone_location_refresh","manual");LocationSnapshot point=LocationSnapshot.fromReply(io.github.polestarcn.companion.api.ProtoWire.decode(io.github.polestarcn.companion.api.ProtoWire.bytesField(2,io.github.polestarcn.companion.api.ProtoWire.concat(io.github.polestarcn.companion.api.ProtoWire.fixed32Field(1,120.5f),io.github.polestarcn.companion.api.ProtoWire.fixed32Field(2,30.25f)))));assertNotNull(point);ParkingWebPreview preview=new ParkingWebPreview(a,point,false,()->{});android.webkit.WebView web=preview.view.findViewWithTag("parking_webview");android.webkit.WebChromeClient chrome=Shadows.shadowOf(web).getWebChromeClient();final boolean[] grant={true};chrome.onGeolocationPermissionsShowPrompt("https://m.amap.com",(origin,allow,retain)->grant[0]=allow);assertFalse(grant[0]);preview.requestPhoneLocation();chrome.onGeolocationPermissionsShowPrompt("https://m.amap.com",(origin,allow,retain)->grant[0]=allow);assertTrue(grant[0]);preview.close();}
 @Test public void chargingSweepFillsTheTextCardAndHasLongCycle()throws Exception{UiSkin.set(a,UiSkin.NIO_LIKE_2);render(360,780,1);View pulse=tag("charging_pulse"),section=tag("charging_section");assertEquals(View.VISIBLE,pulse.getVisibility());assertTrue(pulse.getHeight()>section.getHeight()/2);Field field=ChargingPulseView.class.getDeclaredField("animator");field.setAccessible(true);android.animation.ValueAnimator animator=(android.animation.ValueAnimator)field.get(pulse);if(animator!=null)assertEquals(5000,animator.getDuration());}
 @Test public void backgroundPreferenceReschedulesAndCanRunWithoutResidentNotification(){JobScheduler jobs=(JobScheduler)a.getSystemService(Context.JOB_SCHEDULER_SERVICE);AppPreferences.set(a,"resident","off");AppPreferences.set(a,"app_background_enabled","on");AppPreferences.set(a,"app_background_minutes","60");ResidentService.scheduleUpdates(a);assertEquals(60*60_000L,jobs.getPendingJob(41).getIntervalMillis());AppPreferences.set(a,"app_background_minutes","15");ResidentService.scheduleUpdates(a);assertEquals(15*60_000L,jobs.getPendingJob(41).getIntervalMillis());AppPreferences.set(a,"app_background_minutes","0");AppPreferences.set(a,"widget_refresh_minutes","0");ResidentService.scheduleUpdates(a);assertNull(jobs.getPendingJob(41));}
 @Test public void compactDetailedVoLikeKeepsDataInTheRightRail()throws Exception{UiSkin.set(a,UiSkin.DETAILED);render(320,568,1.3f);assertNotNull(tag("volike_detail_rail"));tag("exterior_button").performClick();assertNotNull(org.robolectric.shadows.ShadowAlertDialog.getLatestAlertDialog().findViewById(android.R.id.content).findViewWithTag("car_condition_popup"));}
 @Test public void widgetProvidersUseTheSameLauncherIconIncludingFiveByOne()throws Exception{android.content.pm.PackageManager pm=a.getPackageManager();android.content.pm.ApplicationInfo app=pm.getApplicationInfo(a.getPackageName(),0);for(Class<?> provider:new Class<?>[]{VehicleWidgetProvider.class,CompactWidgetProvider.class,WideStripWidgetProvider.class,MiniStripWidgetProvider.class,DataWidgetProvider.class,ExtraWideWidgetProvider.class})assertEquals(app.icon,pm.getReceiverInfo(new ComponentName(a,provider),0).icon);}
 private void export(View v,String name,int width,int height)throws Exception{File f=new File("build/reports/previews/v086/"+name+".png");f.getParentFile().mkdirs();Bitmap b=Bitmap.createBitmap(width*2,height*2,Bitmap.Config.ARGB_8888);Canvas c=new Canvas(b);c.scale(2,2);v.draw(c);try(FileOutputStream out=new FileOutputStream(f)){b.compress(Bitmap.CompressFormat.PNG,100,out);}b.recycle();}
 @Test public void exportsImplementedLayouts()throws Exception{UiSkin.set(a,UiSkin.SIMPLE);export(render(360,780,1),"volike-simple",360,780);invoke("toggleVoDetails");export(render(360,780,1),"volike-detail",360,780);UiSkin.set(a,UiSkin.PS_DEFAULT);export(render(360,780,1),"ps-default",360,780);View v=widget(VoLikeWidgetRenderer.PSEU,WidgetRenderer.Size.EXTRA_WIDE,380,70,model.snapshot);export(v,"widget-5x1",380,70);set(a,"page",2);export(render(360,780,1),"settings",360,780);}
